class Revision5:
 def __init__(self):
  self.old=Revision(3)
  for name,glyph in self.old.speed.items():
   count,labels,stats,_=cv2.connectedComponentsWithStats(glyph.astype(np.uint8))
   keep=np.argsort(stats[1:,cv2.CC_STAT_AREA])[-2:]+1
   self.old.speed[name]=np.isin(labels,keep)
  remove={'yellow floor marker first glimpse','yellow floor marker after pan','cabinet tool case brand','cabinet upper small carton Chinese','return large carton Chinese','return carton side Chinese'}
  self.old.base.ts=[tr for tr in self.old.base.ts if tr['name'] not in remove and 'Chinese plot annotation' not in tr['name']]
  for tr in self.old.base.ts:
   if 'introductory' in tr['name']:
    if 31<tr['start']<35:tr['start']=1960/60;tr['end']=2080/60
    if 61<tr['start']<65:tr['start']=3722/60;tr['end']=3850/60
   if tr['name']=='fire extinguisher Chinese':tr['start']=16.866667
 def edited(self,f,im):
  out=self.old.edited(f,im);t=f/60;fine=np.zeros((1080,1920),np.uint8);coarse=fine.copy()
  for keys in [TOP,TOOL,FRONT,SIDE,FLOOR1,FLOOR2,UNDERDESK]:active_rect(keys,t,fine,(3,64,637,426),pad=7)
  active_rect(FACE,t,coarse,(3,64,637,426),pad=7)
  active_rect(OTHER_DOG,t,coarse,(1283,64,1917,426),pad=6)
  p=pixels(im,fine);out[fine>0]=p[fine>0]
  if coarse.any():
   p=cv2.resize(cv2.resize(im,(96,54),interpolation=cv2.INTER_AREA),(1920,1080),interpolation=cv2.INTER_NEAREST);out[coarse>0]=p[coarse>0]
  if fine[74:192,14:178].any() or coarse[74:192,14:178].any():
   patch=out[74:192,14:178];patch[:]=24;glyph=self.old.speed['6X'];patch[glyph]=im[74:192,14:178][glyph]
  return out

